const leads = $input.all().map(i => i.json);
const flatLeads = Array.isArray(leads[0]) ? leads[0] : leads;

// CSV 형식으로 변환
const headers = ['No','이름','전화번호','이메일','상호명','업종','니즈','등급','스코어','출처','수집일','사업부','담당'];
let csv = headers.join(',') + '\n';

flatLeads.forEach((l, i) => {
  const row = [
    i + 1,
    l.name || '',
    l.phone || '',
    l.email || '',
    l.company || '',
    (l.interest || []).join(';'),
    l.need || '',
    l.grade || '',
    l.score || 0,
    l.source || '',
    l.created_at ? l.created_at.split('T')[0] : '',
    l.business_unit || '',
    l.assigned_to || ''
  ].map(v => `"${String(v).replace(/"/g, '""')}"`);
  csv += row.join(',') + '\n';
});

// 사업부별 요약
const units = { pension: 'A-달팽이', cnc: 'B-스토리팜', automation: 'C-AI자동화', webdev: 'D-웹개발' };
const summary = {};
flatLeads.forEach(l => {
  const u = l.business_unit;
  if (!summary[u]) summary[u] = { total: 0, hot: 0, warm: 0, cold: 0 };
  summary[u].total++;
  summary[u][l.stage || 'cold']++;
});

let report = `📊 **주간 가망고객 수집 리포트**\n━━━━━━━━━━━━━━━━━━\n`;
report += `📅 ${new Date(Date.now()-7*86400000).toLocaleDateString('ko-KR')} ~ ${new Date().toLocaleDateString('ko-KR')}\n\n`;
report += `📦 **총 수집: ${flatLeads.length}건**\n\n`;

Object.entries(summary).forEach(([u, s]) => {
  report += `🏢 ${units[u] || u}: ${s.total}건 (Hot:${s.hot||0} Warm:${s.warm||0} Cold:${s.cold||0})\n`;
});

return [{ json: { csv, report, total: flatLeads.length }, binary: {} }];
